#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

triu_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#define TRIU_CP_ASYNC 1
#else
#define TRIU_CP_ASYNC 0
#endif

#include <cute/tensor.hpp>

using namespace cute;

// C = triu(A @ B) for upper triangular A, B (row-major N x N).
// One fused kernel: tiled GEMM + triangular masking, exploiting that
// A[m,k] = 0 for k < m and B[k,n] = 0 for k > n.
template <typename T>
__global__ static void triu_gemm_kernel(const T* __restrict__ Ap,
                                        const T* __restrict__ Bp,
                                        T* __restrict__ Cp,
                                        int N)
{
  const int bx  = blockIdx.x;   // M-tile index
  const int by  = blockIdx.y;   // N-tile index
  const int tid = threadIdx.x;
  // Warp-level tiling: the 8 warps of the CTA are arranged as a (4,2)
  // grid, each warp owning a 32x64 sub-tile of the 128x128 CTA tile.
  // Within a warp the 32 lanes form a (4,8) grid, so each thread owns
  // an 8x8 register tile; A fragments are broadcast 8-way and B
  // fragments 4-way across each warp, reducing shared-memory traffic.
  const int warp   = tid >> 5;
  const int lane   = tid & 31;
  const int warp_m = (warp & 3) * 32;
  const int warp_n = (warp >> 2) * 64;
  const int lane_m = (lane & 3) * 8;
  const int lane_n = (lane >> 2) * 8;
  const int tm = warp_m + lane_m;   // row offset of this thread's 8x8 tile
  const int tn = warp_n + lane_n;   // col offset of this thread's 8x8 tile
  const int c_row = bx * 128 + tm;
  const int c_col = by * 128 + tn;
  T* Ctile = Cp + (size_t)c_row * N + c_col;   // 32B-aligned (c_col % 8 == 0)
  // Tiles entirely below the diagonal are exactly zero after triu.
  if (bx > by) {
    const float4 z4 = make_float4(0.f, 0.f, 0.f, 0.f);
    CUTE_UNROLL
    for (int i = 0; i < 8; ++i) {
      *reinterpret_cast<float4*>(Ctile + (size_t)i * N)     = z4;
      *reinterpret_cast<float4*>(Ctile + (size_t)i * N + 4) = z4;
    }
    return;
  }
  // Multi-stage (4-deep) cp.async pipeline: keep three K-tiles in flight
  // while the gemm consumes the oldest, hiding global-memory latency far
  // better than the previous double buffer. Same swizzled A layout and
  // padded B layout; K-tile depth (8) and staging pattern are unchanged.
  constexpr int STAGES = 4;   // power of two so buffer index is a mask
  __shared__ __align__(16) T smemA[STAGES][128 * 8];
  __shared__ __align__(16) T smemB[STAGES][8 * 132];
  auto sA_layout = composition(Swizzle<3,2,4>{},
                               make_layout(make_shape(Int<128>{}, Int<8>{}),
                                           make_stride(Int<8>{}, Int<1>{})));
  // Vectorized gmem->smem staging: one 16B float4 per thread per operand tile.
  const int a_row  = tid >> 1;            // 0..127 rows of sA
  const int a_col4 = (tid & 1) * 4;       // two float4 per 8-wide K row
  const int b_row  = tid >> 5;            // 0..7 rows of sB
  const int b_col4 = (tid & 31) * 4;      // 32 float4 per 128-wide N row
  const int a_off = (int)sA_layout(a_row, a_col4);
  float acc[8][8];
  CUTE_UNROLL
  for (int i = 0; i < 8; ++i)
    CUTE_UNROLL
    for (int j = 0; j < 8; ++j)
      acc[i][j] = 0.f;
  // Only K-tiles covering k in [128*bx, 128*by+127] can contribute.
  constexpr int kKTilesPerCta = 128 / 8;   // 16
  const int kt_begin = bx * kKTilesPerCta;
  const int kt_end   = (by + 1) * kKTilesPerCta;
  auto stage_tile = [&](int kt, int buf) {
    const float4* gA4 = reinterpret_cast<const float4*>(
        Ap + (size_t)(bx * 128 + a_row) * N + kt * 8 + a_col4);
    const float4* gB4 = reinterpret_cast<const float4*>(
        Bp + (size_t)(kt * 8 + b_row) * N + by * 128 + b_col4);
#if TRIU_CP_ASYNC
    __pipeline_memcpy_async(&smemA[buf][a_off], gA4, 16);
    __pipeline_memcpy_async(&smemB[buf][b_row * 132 + b_col4], gB4, 16);
#else
    *reinterpret_cast<float4*>(&smemA[buf][a_off]) = *gA4;
    *reinterpret_cast<float4*>(&smemB[buf][b_row * 132 + b_col4]) = *gB4;
#endif
  };
  // Prologue: asynchronously stage the first STAGES-1 K-tiles (one commit
  // group per stage). kt_end-kt_begin >= 16 > STAGES-1 for bx <= by.
#if TRIU_CP_ASYNC
  CUTE_UNROLL
  for (int s = 0; s < STAGES - 1; ++s) {
    stage_tile(kt_begin + s, s);
    __pipeline_commit();
  }
#else
  stage_tile(kt_begin, 0);
#endif
  // Main pipelined loop: issue the tile STAGES-1 ahead (empty commit near
  // the tail keeps the group count invariant), then wait so the oldest
  // tile is complete while up to STAGES-2 newer tiles remain in flight.
  for (int kt = kt_begin; kt < kt_end; ++kt) {
    const int p = kt - kt_begin;
#if TRIU_CP_ASYNC
    const int buf = p & (STAGES - 1);
    const int nxt = kt + STAGES - 1;
    if (nxt < kt_end) {
      stage_tile(nxt, (p + STAGES - 1) & (STAGES - 1));
    }
    __pipeline_commit();            // commit every iter (possibly empty)
    __pipeline_wait_prior(STAGES - 2);
#else
    const int buf = 0;
    if (kt != kt_begin) {
      stage_tile(kt, 0);
    }
#endif
    __syncthreads();
    const T* sA = smemA[buf];
    const T* sB = smemB[buf];
    // Warp-tile inner loop: each warp reads only its own 32x8 A sub-tile
    // (8-way lane broadcast) and 8x64 B sub-tile (4-way lane broadcast,
    // 16B vectorized loads), then accumulates an 8x8 register tile.
    CUTE_UNROLL
    for (int k = 0; k < 8; ++k) {
      float a_frag[8];
      CUTE_UNROLL
      for (int i = 0; i < 8; ++i)
        a_frag[i] = sA[(int)sA_layout(tm + i, k)];
      const float4* sB4 = reinterpret_cast<const float4*>(&sB[k * 132 + tn]);
      const float4 b0 = sB4[0];
      const float4 b1 = sB4[1];
      const float b_frag[8] = {b0.x, b0.y, b0.z, b0.w, b1.x, b1.y, b1.z, b1.w};
      CUTE_UNROLL
      for (int i = 0; i < 8; ++i)
        CUTE_UNROLL
        for (int j = 0; j < 8; ++j)
          acc[i][j] = fmaf(a_frag[i], b_frag[j], acc[i][j]);
    }
    __syncthreads();
  }
  if (bx == by) {
    // Diagonal tile: apply the triu mask in the epilogue.
    const int m_base = bx * 128;
    const int n_base = by * 128;
    CUTE_UNROLL
    for (int i = 0; i < 8; ++i) {
      const int m = m_base + tm + i;
      float out[8];
      CUTE_UNROLL
      for (int j = 0; j < 8; ++j) {
        const int n = n_base + tn + j;
        out[j] = (m <= n) ? acc[i][j] : 0.f;
      }
      *reinterpret_cast<float4*>(Ctile + (size_t)i * N) =
          make_float4(out[0], out[1], out[2], out[3]);
      *reinterpret_cast<float4*>(Ctile + (size_t)i * N + 4) =
          make_float4(out[4], out[5], out[6], out[7]);
    }
  } else {
    // Strictly above-diagonal tile: every element is kept; vectorized stores.
    CUTE_UNROLL
    for (int i = 0; i < 8; ++i) {
      *reinterpret_cast<float4*>(Ctile + (size_t)i * N) =
          make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
      *reinterpret_cast<float4*>(Ctile + (size_t)i * N + 4) =
          make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
    }
  }
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int64_t N = A.size(0);
  TORCH_CHECK(A.size(1) == N && B.size(0) == N && B.size(1) == N,
              "A and B must be square N x N with the same N");
  TORCH_CHECK(N % 128 == 0, "N must be a multiple of 128");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({N, N}, A.options());

  dim3 block(256);
  dim3 grid((unsigned)(N / 128), (unsigned)(N / 128));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triu_gemm_kernel<float><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)N);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_gemm_kernel launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

triu_ext = load_inline(
    name="cute_triu_gemm_ext",
    cpp_sources=triu_cpp_decl,
    cuda_sources=triu_cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
